-- 21-oct-2026 · Snippets con SECUENCIA: un snippet puede mandar varios mensajes
-- seguidos con un solo clic (texto, documento, imágenes y el acceso a la prueba).
--
-- pasos = arreglo JSON, en orden. Cada paso:
--   {"tipo":"texto","texto":"…"}                         (admite {{primer_nombre}} etc.)
--   {"tipo":"documento","url":"https://…","nombre":"x.pdf","caption":"…"}
--   {"tipo":"imagen","url":"https://…","caption":"…"}
--   {"tipo":"acceso_prueba","dias":7,"texto":"… {{url}} {{cuenta}} {{correo}} {{contrasena}} {{dias}}"}
--     → crea la cuenta de prueba (POST /api/crm/sacs-prueba) y manda el texto con los datos.
-- null o [] = snippet normal de siempre.

alter table wa_respuestas add column if not exists pasos jsonb;

-- El snippet de la prueba gratis, listo (no pisa uno existente con el mismo atajo).
insert into wa_respuestas (atajo, titulo, categoria, texto, media_tipo, pasos)
select 'pruebagratis', 'Prueba gratis · paquete completo', 'ventas',
       '🎁 Prueba gratis: texto por puntos + PDF + 5 imágenes + acceso (un clic)',
       'text', $j$[{"tipo": "texto", "texto": "¡Hola {{primer_nombre}}! 👋 Te damos la bienvenida a tu *prueba gratis de Sacs*. Aquí tienes todo lo que incluye, punto por punto:\n\n*1️⃣ Tu prueba: 7 días con todo Sacs*\nTienes el *plan Fideliza completo*, que incluye todo lo de Vende y Controla, más Fideliza:\n• Punto de venta (con y sin internet), cortes de caja y tickets por WhatsApp\n• Tienda en línea, Facebook, Instagram, WhatsApp y TikTok Shop\n• Inventario en todas tus tiendas, traspasos, conteos, compras y gastos\n• 50+ reportes, metas y comisiones\n• Clientes que regresan: puntos, monedero, tarjetas de regalo, membresías y avisos por WhatsApp y correo\n\n*2️⃣ AXO Pro incluido (valor $3,000 al mes + IVA)*\nAXO es la inteligencia artificial de Sacs y en tu prueba lo usas sin costo:\n• Te arma tu plan de onboarding, paso a paso\n• Te explica cualquier pantalla o proceso\n• Te capacita a ti y a tu equipo\n• Importa tus productos desde tu Excel o tu sistema anterior\n• Consulta lo que quieras: «¿Cuánto vendí hoy?», «¿Cómo hago un traspaso?»\n• Te hace tu *tienda en línea en menos de 30 minutos*: le pides cómo la quieres y te la prepara\n• *Migra tu información sin formatos raros*: le pasas tu base de datos como la tengas y la deja cargada (migración incluida, en 30 minutos como máximo)\n\n*3️⃣ Beneficio solo durante tus 7 días*\nSi contratas *cualquier plan* dentro de tus 7 días de prueba y lo pagas anual:\n• *45% de descuento*\n• *AXO incluido sin pagar nada extra*\nPrecio por todo el año con el 45% aplicado:\n• Vende: ~$9,720~ → *$5,346 al año* (equivale a $445.50 al mes)\n• Controla: ~$14,580~ → *$8,019 al año* (equivale a $668.25 al mes)\n• Fideliza: ~$22,680~ → *$12,474 al año* (equivale a $1,039.50 al mes)\n⚠️ Pasando el día 7, este beneficio ya no aplica.\n\n*4️⃣ Academia*\nSi prefieres aprender con algo gráfico o en video, la *Academia de Sacs* tiene toda la información del sistema, dentro de la plataforma.\n\n*5️⃣ Soporte 24/7*\n• Pregunta lo que quieras, a cualquier hora, a *AXO y a nuestros asesores*, dentro de la plataforma\n• No solo te contestamos: te decimos *cómo hacerlo, paso a paso*\n\n*6️⃣ Importante: este chat es de ventas, no de soporte*\nPor este chat *no se resuelven dudas del sistema*. Todo el soporte es *únicamente a través de la plataforma*.\n\n*7️⃣ Día 7: cierre de tu prueba*\nEl *día 7 exacto*, si no tenemos respuesta de tu parte, *tu cuenta se cancela*.\n\n📄 Toda la información, con fotos: https://www.sacscloud.com/tu-prueba-gratis/\n\n¡Aprovecha tus 7 días! 🚀"}, {"tipo": "documento", "url": "https://www.sacscloud.com/tu-prueba-gratis/Sacs-Prueba-Gratis.pdf", "nombre": "Sacs-Prueba-Gratis.pdf", "caption": "📄 Aquí tienes toda la información de tu prueba gratis.\nTambién la puedes ver en: https://www.sacscloud.com/tu-prueba-gratis/"}, {"tipo": "imagen", "url": "https://www.sacscloud.com/tu-prueba-gratis/imagenes/Sacs-prueba-1-que-incluye.jpg"}, {"tipo": "imagen", "url": "https://www.sacscloud.com/tu-prueba-gratis/imagenes/Sacs-prueba-2-axo-incluido.jpg"}, {"tipo": "imagen", "url": "https://www.sacscloud.com/tu-prueba-gratis/imagenes/Sacs-prueba-3-tienda-en-linea.jpg"}, {"tipo": "imagen", "url": "https://www.sacscloud.com/tu-prueba-gratis/imagenes/Sacs-prueba-4-migracion.jpg"}, {"tipo": "imagen", "url": "https://www.sacscloud.com/tu-prueba-gratis/imagenes/Sacs-prueba-5-descuento-7-dias.jpg"}, {"tipo": "acceso_prueba", "dias": 7, "texto": "🔑 *Tu acceso a Sacs*\n\nEntra en: {{url}}\nCuenta: {{cuenta}}\nCorreo: {{correo}}\nContraseña: {{contrasena}}\n\nTu prueba dura {{dias}} días. La contraseña la puedes cambiar en cuanto entres.\n\nCualquier duda del sistema, pregúntale a AXO o a nuestros asesores *dentro de la plataforma*, 24/7 🙌"}]$j$::jsonb
where not exists (select 1 from wa_respuestas where atajo = 'pruebagratis');
